/bin/bash -lc "ls -la && python - <<'PY'
from pathlib import Path
import re, unicodedata
for p in sorted(Path('.').rglob('*')):
    if p.is_file():
        print(f'\\n{p}:')
        s=p.read_text()
        for n,line in enumerate(s.splitlines(),1):
            print(f'{n}: {line}')
            for x in re.findall(r'"'`([''^`]+)`'"',line):
                print('   Caractere:', ', '.join(f'{c"'!r}=U+{ord(c):04X} ({unicodedata.name(c,"UNKNOWN")})'"' for c in x))
PY"

